/**
 * The checklist library for manual social media audits. Nothing here is generated by AI:
 * these are the checkpoints an auditor works through and marks as they review the accounts.
 */

export const PLATFORMS = [
  { key: "instagram", label: "Instagram" },
  { key: "facebook", label: "Facebook" },
  { key: "linkedin", label: "LinkedIn" },
  { key: "youtube", label: "YouTube" },
  { key: "x", label: "X (Twitter)" },
  { key: "tiktok", label: "TikTok" },
  { key: "pinterest", label: "Pinterest" },
] as const;
export type PlatformKey = (typeof PLATFORMS)[number]["key"];
export const platformLabel = (k: string) => PLATFORMS.find((p) => p.key === k)?.label ?? k;

export type LibrarySection = { key: string; title: string; description: string; group: "general" | "platform"; platform?: PlatformKey; items: string[] };

