export const GENERAL_SECTIONS = LIBRARY.filter((s) => s.group === "general");
export const PLATFORM_SECTIONS = LIBRARY.filter((s) => s.group === "platform");
export const getLibrarySection = (key: string) => LIBRARY.find((s) => s.key === key) ?? null;
